336	// printCreatedTrail reports a newly created trail, including its browser URL
337	// (the same URL `trail show` surfaces) when one is available.
338	func printCreatedTrail(w io.Writer, t api.TrailResource, forge, owner, repo string) {
339		if t.Branch == "" {
340			fmt.Fprintf(w, "Created trail %q (ID: %s)\n", t.Title, t.ID)
341		} else {
342			fmt.Fprintf(w, "Created trail %q for branch %s (ID: %s)\n", t.Title, t.Branch, t.ID)
343		}
344		if url := trailDisplayURL(t, forge, owner, repo); url != "" {
345			fmt.Fprintf(w, "  URL: %s\n", url)
346		}
347	}
348	
349	// trailDisplayURL returns the trail's browser URL. It prefers the canonical URL
350	// the server now returns, so the CLI tracks any route change without being
351	// updated in lockstep, and falls back to a locally constructed URL only for
352	// older servers that omit the field.
353	func trailDisplayURL(t api.TrailResource, forge, owner, repo string) string {
354		if strings.TrimSpace(t.URL) != "" {
355			return t.URL
356		}
357		if t.Number > 0 {
358			return trailWebURL(api.BaseURL(), forge, owner, repo, t.Number)
359		}
360		return ""
361	}
362	
363	// trailWebURL builds a fallback browser URL for a trail used only when the
364	// server does not supply one (older servers):
365	// <web-origin>/<forge>/<owner>/<repo>/trails/<number>. In production the web app
366	// is served from the same origin as the data API, so the API base URL doubles
367	// as the web origin. A split local-dev setup (API and frontend on different
368	// ports) would point this at the API port rather than the dev frontend.
369	func trailWebURL(base, forge, owner, repo string, number int) string {
370		return strings.TrimRight(base, "/") + "/" + forge + "/" + owner + "/" + repo + "/trails/" + strconv.Itoa(number)
371	}
372	
373	// fetchTrailDescription fetches a trail's rendered description text
374	// (`trail.body_document.text_snapshot`), which the list endpoint omits, by
375	// integer number. It returns only the description — the list result already
376	// supplies the metadata — and decodes only the fields it needs, so it is
377	// unaffected by the shape of sibling fields like `checkpoints`/`thread`.
378	func fetchTrailDescription(ctx context.Context, client *api.Client, forge, owner, repo string, number int) (string, error) {
379		resp, err := client.Get(ctx, trailNumberPath(forge, owner, repo, number))
380		if err != nil {
381			return "", fmt.Errorf("failed to fetch trail detail: %w", err)
382		}
383		defer resp.Body.Close()
384		if err := checkTrailResponse(resp); err != nil {
385			return "", err
386		}
387		var detail struct {
388			Trail api.TrailResource `json:"trail"`
389		}
390		if err := api.DecodeJSON(resp, &detail); err != nil {
391			return "", fmt.Errorf("failed to decode trail detail: %w", err)
392		}
393		if detail.Trail.BodyDocument == nil {
394			return "", nil
395		}
396		return strings.TrimSpace(detail.Trail.BodyDocument.TextSnapshot), nil
397	}
